function validate([nums]) {
  if (nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 10^5 numbers.';
  if (nums.some(v => v < 1 || v >= 1e9)) return 'Each number is from 1 to 10^9 - 1.';
  const digits = String(nums[0]).length;
  if (nums.some(v => String(v).length !== digits)) return 'All numbers must have the same number of digits.';
  return null;
}

