function sumDigitDifferences(nums) {
  const n = nums.length;
  const digits = String(nums[0]).length;
  let total = 0;
  let place = 1;
  for (let position = 0; position < digits; position++) {
    // count[d] is how many numbers have digit d at this position.
    const count = new Array(10).fill(0);
    for (const value of nums) {
      const digit = Math.floor(value / place) % 10;
      count[digit]++;
    }
    for (let d = 0; d < 10; d++) {
      // The count[d] numbers with digit d differ here from the other n - count[d].
      total += count[d] * (n - count[d]);
    }
    place *= 10;
  }
  // Each differing pair was counted twice, once from each of its numbers.
  return total / 2;
}

