function sumDigitDifferences(nums) {
  // Compare every pair of numbers character by character as decimal strings of equal length.
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const a = String(nums[i]), b = String(nums[j]);
      for (let p = 0; p < a.length; p++) if (a[p] !== b[p]) total++;
    }
  }
  return total;
}

