function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(2, 8);
  const digits = large ? int(6, 9) : int(1, 9);
  // Each position draws its digits from a short random range, so equal digits (and equal numbers) are common.
  // The leading position never uses 0, so every number has exactly `digits` digits.
  const ranges = Array.from({ length: digits }, (_, p) => {
    const low = int(p === 0 ? 1 : 0, 9);
    return [low, Math.min(9, low + int(0, large ? 9 : 4))];
  });
  const nums = Array.from({ length: n }, () => {
    let value = 0;
    for (const [low, high] of ranges) value = value * 10 + int(low, high);
    return value;
  });
  return [nums];
}
